              {allProfs.filter(p => p.statut_validation === 'validé').slice(0, 4).map(p => (
                <div key={p.id} onClick={() => { setTab('profs'); setSelectedProf(p); }} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid var(--border)', cursor: 'pointer' }}>
