              <div style={{ color: '#f59e0b', fontWeight: 700, fontSize: '.88rem', marginBottom: 14 }}>⚠️ {pendingProfs.length} PROFESSEUR{pendingProfs.length > 1 ? 'S' : ''} EN ATTENTE DE VALIDATION</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 10 }}>
                {pendingProfs.map(p => {
