                  {s.label}
                  <span style={{ background: filterStatut === s.key ? s.color : 'var(--border)', color: filterStatut === s.key ? '#000' : 'var(--text2)', fontSize: '.62rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>{counts[s.key]}</span>
