            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
              {villes.map(v => <span key={v.id} style={{ background: 'var(--surface2)', padding: '8px 16px', borderRadius: 12, border: '1px solid var(--border)', fontSize: '.9rem' }}>{v.nom}</span>)}
