                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                      {niv.matieres?.map(m => (
                        <div key={m.id} style={{ background: 'var(--card)', padding: '6px 12px', borderRadius: 8, fontSize: '.8rem', border: '1px solid var(--border)', display: 'flex', gap: 8, alignItems: 'center' }}>
                          {m.nom}<span style={{ color: '#ff6584', cursor: 'pointer', fontSize: '.75rem' }}>✕</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* MODALE AJOUT MATIÈRE */}
      {showAddMat && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 32, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
            <h3 style={{ marginBottom: 20, marginTop: 0 }}>Nouvelle matière</h3>
            <form onSubmit={handleAddMatiere} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <input style={{ width: '100%', background: 'var(--surface2)', border: '1px solid var(--border)', padding: 12, borderRadius: 10, color: '#fff', outline: 'none' }} placeholder="Nom de la matière" value={newMat.nom} onChange={e => setNewMat({ ...newMat, nom: e.target.value })} required />
              <div style={{ display: 'flex', gap: 10 }}>
                <button type="submit" style={{ flex: 2, background: '#6c63ff', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}>Enregistrer</button>
                <button type="button" onClick={() => setShowAddMat(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, cursor: 'pointer' }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ProfDrawer prof={selectedProf} onClose={() => setSelectedProf(null)} onValider={handleValider} onRefuser={handleRefuser} />
    </div>
  );
}
